import{_ as i,o as n,c as r,j as e,a as t,aa as s}from"./chunks/framework.BAs_AphD.js";const o="/buildary-help-preview/media/en/diary/en_dennizaznamyosoby2.jpg",l="/buildary-help-preview/media/en/diary/en_dennizaznamymechanizmy.jpg",d="/buildary-help-preview/media/en/diary/en_dennizaznamymaterialy.jpg",g=JSON.parse('{"title":"Daily Entries - Labour, Plants and Materials","description":"","frontmatter":{"title":"Daily Entries - Labour, Plants and Materials","wiki":"en:diary:dailyentriespersons"},"headers":[],"relativePath":"en/diary/dailyentriespersons.md","filePath":"en/diary/dailyentriespersons.md","lastUpdated":1795418601000}'),c={name:"en/diary/dailyentriespersons.md"};function p(h,a,y,u,m,b){return n(),r("div",null,[...a[0]||(a[0]=[e("h1",{id:"daily-entries-labour-plants-and-materials",tabindex:"-1"},[t("Daily Entries - Labour, Plants and Materials "),e("a",{class:"header-anchor",href:"#daily-entries-labour-plants-and-materials","aria-label":'Permalink to "Daily Entries - Labour, Plants and Materials"'},"​")],-1),e("h3",{id:"video-for-the-labour-plants-and-materials-section",tabindex:"-1"},[t("Video for the Labour, Plants and Materials Section "),e("a",{class:"header-anchor",href:"#video-for-the-labour-plants-and-materials-section","aria-label":'Permalink to "Video for the Labour, Plants and Materials Section"'},"​")],-1),e("div",{class:"video"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/i1anbZAi1xA",title:"YouTube video",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),s('<h2 id="labour" tabindex="-1">Labour <a class="header-anchor" href="#labour" aria-label="Permalink to &quot;Labour&quot;">​</a></h2><p>This is a list of all people working at the construction site on a given day. According to Decree No. 499/2006 Coll., the list should identify individuals by name. However, it is up to the user to decide whether to record people by name or use another method.</p><figure class="shot" style="--w:600px;"><img src="'+o+'" alt="" width="600" loading="lazy"></figure><p>To add a new item (person), fill in the editing window that opens when you select the <strong>+ New Entry</strong> button. The application remembers saved items. If you want to enter a person who has already been recorded in the past, the application will offer matching saved items as you gradually type the person&#39;s name in the editing window. Selecting the suggested entry will copy all data from the previous record and pre-fill the other fields, where the information can be edited.</p><p>The full list of saved entries can be displayed in the editing window by expanding the dropdown list in the item name field and selecting the required item directly.</p><p>Another option for adding data to the section is to copy data from another day of the diary and then edit it if necessary.</p><p>You can add a <strong>Note</strong> to this section, which is saved using a separate button. Specifically for this section, you can preset the content of the note when recording working hours. This is configured under Diary Settings → <strong>Working Hours</strong> field (see <a href="/buildary-help-preview/en/diary/diarysetup#diary-settings">Diary Settings</a>).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Lists of items available for selection can be prepared in advance under Project Settings → Code Lists - Project Diary → Labor on Site / Plants / Materials sub-tabs, either by adding items individually or by importing an XLS file (see <a href="/buildary-help-preview/en/diary/projectsetup#code-lists-project-diary">Code Lists - Project Diary</a>). The same principle applies to the Plants and Materials sections.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>People on site can be imported into the diary from the project&#39;s attendance system (Convision, Sysdo, WinPak, AdamAssistant or Fingera). You set up the connection yourself in the domain settings – see <a href="/buildary-help-preview/en/diary/attendance_system">Project Attendance System</a>.</p></div><h2 id="plants-materials" tabindex="-1">Plants, Materials <a class="header-anchor" href="#plants-materials" aria-label="Permalink to &quot;Plants, Materials&quot;">​</a></h2><p>Data entry works similarly to the Labour section. The available fields are determined by the Diary Settings. In these sections, you can add a note, which is saved using a separate button.</p><img src="'+l+'" alt="" width="600" loading="lazy"><img src="'+d+'" alt="" width="600" loading="lazy">',13)])])}const w=i(c,[["render",p]]);export{g as __pageData,w as default};
